@@ -0,0 +1,187 @@
+package agent
+
+import (
+	"context"
+	"errors"
+	"fmt"
+	"sync"
+
+	"px1/internal/hosted/review"
+)
+
+// OrgLimiter caps concurrently running sub-agents per installation across all
+// reviews in this process, so one large organization cannot starve others.
+// It is process-local: N workers allow up to N × limit per installation.
+type OrgLimiter struct {
+	limit int
+	mu    sync.Mutex
+	slots map[int64]*orgSlot
+}
+
+type orgSlot struct {
+	sem   chan struct{}
+	users int
+}
+
+func NewOrgLimiter(limit int) (*OrgLimiter, error) {
+	if limit <= 0 {
+		return nil, errors.New("per-organization concurrency limit must be positive")
+	}
+	return &OrgLimiter{limit: limit, slots: map[int64]*orgSlot{}}, nil
+}
+
+// Acquire blocks until the installation has a free slot or ctx ends. Idle
+// installations are forgotten so the map does not grow with tenant count.
+func (l *OrgLimiter) Acquire(ctx context.Context, installationID int64) (func(), error) {
+	l.mu.Lock()
+	slot := l.slots[installationID]
+	if slot == nil {
+		slot = &orgSlot{sem: make(chan struct{}, l.limit)}
+		l.slots[installationID] = slot
+	}
+	slot.users++
+	l.mu.Unlock()
+	leave := func() {
+		l.mu.Lock()
+		if slot.users--; slot.users == 0 {
+			delete(l.slots, installationID)
+		}
+		l.mu.Unlock()
+	}
+	select {
+	case slot.sem <- struct{}{}:
+		var once sync.Once
+		return func() { once.Do(func() { <-slot.sem; leave() }) }, nil
+	case <-ctx.Done():
+		leave()
+		return nil, ctx.Err()
+	}
+}
+
+// SubAgent runs one planned task to completion: the model and tool loop that
+// spends from meter. It returns candidate findings for the judge.
+type SubAgent func(ctx context.Context, task PlanTask, meter *Meter) ([]review.Finding, error)
+
+type TaskOutcome string
+
+const (
+	TaskCompleted TaskOutcome = "completed"
+	TaskFailed    TaskOutcome = "failed"
+	TaskSkipped   TaskOutcome = "skipped"
+)
+
+// Partial is streamed as each task finishes so the summary can post early.
+// Its findings are provisional: they have not been judged or verified and
+// must be labelled that way wherever they are shown.
+type Partial struct {
+	BlockID     string
+	Outcome     TaskOutcome
+	Reason      string
+	Findings    []review.Finding
+	Provisional bool
+	Done, Total int
+}
+
+type RunResult struct {
+	Candidates []review.Finding
+	Outcomes   map[string]Partial
+	Complete   bool
+}
+
+type Runner struct {
+	Limiter   *OrgLimiter
+	SubAgent  SubAgent
+	OnPartial func(Partial)
+}
+
+// Run starts every task in parallel, subject to the organization limit and
+// the review's wall-time deadline. A failed or panicking sub-agent becomes a
+// failed task, not a failed review. Once any budget is exhausted, tasks that
+// have not started yet are skipped with that reason. OnPartial is called
+// from this goroutine only, one task at a time, in completion order.
+func (r Runner) Run(ctx context.Context, installationID int64, tasks []PlanTask, meter *Meter) (RunResult, error) {
+	if r.Limiter == nil || r.SubAgent == nil || meter == nil || installationID <= 0 {
+		return RunResult{}, errors.New("runner needs a limiter, sub-agent, meter, and tenant")
+	}
+	if len(tasks) == 0 || len(tasks) > meter.budget.MaxSubAgents {
+		return RunResult{}, fmt.Errorf("run needs 1 to %d tasks", meter.budget.MaxSubAgents)
+	}
+	seen := map[string]bool{}
+	for _, task := range tasks {
+		if task.BlockID == "" || seen[task.BlockID] {
+			return RunResult{}, errors.New("tasks need unique change-group IDs")
+		}
+		seen[task.BlockID] = true
+	}
+	ctx, cancel := context.WithDeadline(ctx, meter.Deadline())
+	defer cancel()
+
+	results := make(chan Partial, len(tasks))
+	for _, task := range tasks {
+		go func() { results <- r.runOne(ctx, installationID, task, meter) }()
+	}
+
+	byBlock := make(map[string]Partial, len(tasks))
+	for done := 1; done <= len(tasks); done++ {
+		partial := <-results
+		partial.Done, partial.Total = done, len(tasks)
+		byBlock[partial.BlockID] = partial
+		if r.OnPartial != nil {
+			r.OnPartial(partial)
+		}
+	}
+
+	result := RunResult{Outcomes: byBlock, Complete: true}
+	for _, task := range tasks {
+		partial := byBlock[task.BlockID]
+		result.Candidates = append(result.Candidates, partial.Findings...)
+		result.Complete = result.Complete && partial.Outcome == TaskCompleted
+	}
+	return result, nil
+}
+
+func (r Runner) runOne(ctx context.Context, installationID int64, task PlanTask, meter *Meter) (partial Partial) {
+	partial = Partial{BlockID: task.BlockID, Provisional: true}
+	release, err := r.Limiter.Acquire(ctx, installationID)
+	if err != nil {
+		partial.Outcome, partial.Reason = TaskSkipped, "review deadline reached before a sub-agent slot was free"
+		return partial
+	}
+	defer release()
+	if limit := meter.Spend().Exhausted; limit != "" {
+		partial.Outcome, partial.Reason = TaskSkipped, "review budget exhausted ("+limit+") before this task started"
+		return partial
+	}
+	defer func() {
+		if recovered := recover(); recovered != nil {
+			partial = Partial{BlockID: task.BlockID, Outcome: TaskFailed, Reason: "sub-agent panicked", Provisional: true}
+		}
+	}()
+	findings, err := r.SubAgent(ctx, task, meter)
+	if err != nil {
+		partial.Outcome, partial.Reason = TaskFailed, failureReason(err)
+		partial.Findings = findings
+		return partial
+	}
+	partial.Outcome, partial.Findings = TaskCompleted, findings
+	return partial
+}
+
+// failureReason keeps provider and tool error text out of PR summaries; only
+// the class of failure is reported.
+func failureReason(err error) string {
+	switch {
+	case errors.Is(err, ErrBudgetExhausted):
+		return "review budget exhausted during this task"
+	case errors.Is(err, ErrToolCallLimit):
+		return "sub-agent reached its tool-call limit"
+	case errors.Is(err, ErrBudgetContended):
+		return "review budget was held by other in-flight sub-agents"
+	case errors.Is(err, context.DeadlineExceeded):
+		return "review wall time reached during this task"
+	case errors.Is(err, context.Canceled):
+		return "review cancelled"
+	default:
+		return "sub-agent failed"
+	}
+}

diff --git a/internal/hosted/agent/run_test.go b/internal/hosted/agent/run_test.go
new file mode 100644
index 0000000..cb8fdec
--- /dev/null
+++ b/internal/hosted/agent/run_test.go
@@ -0,0 +1,220 @@
+package agent
+
+import (
+	"context"
+	"errors"
+	"fmt"
+	"strings"
+	"sync"
+	"sync/atomic"
+	"testing"
+	"time"
+
+	"px1/internal/hosted/review"
+)
+
+func runBudget(subAgents int, wall time.Duration) Budget {
+	return Budget{MaxSubAgents: subAgents, MaxInputTokens: 1_000, MaxOutputTokens: 1_000, MaxCostMicrousd: 1_000, MaxModelCalls: 100, MaxToolCallsPerAgent: 5, WallTime: wall}
+}
+
+func tasksFor(ids ...string) []PlanTask {
+	tasks := make([]PlanTask, len(ids))
+	for i, id := range ids {
+		tasks[i] = PlanTask{BlockID: id, Focus: "check " + id}
+	}
+	return tasks
+}
+
+func TestRunnerCapsConcurrencyPerOrganization(t *testing.T) {
+	limiter, _ := NewOrgLimiter(2)
+	var active, peak atomic.Int32
+	agent := func(ctx context.Context, task PlanTask, _ *Meter) ([]review.Finding, error) {
+		now := active.Add(1)
+		for {
+			old := peak.Load()
+			if now <= old || peak.CompareAndSwap(old, now) {
+				break
+			}
+		}
+		time.Sleep(10 * time.Millisecond)
+		active.Add(-1)
+		return []review.Finding{finding(task.BlockID+".go", 1, 1, "P2")}, nil
+	}
+	runner := Runner{Limiter: limiter, SubAgent: agent}
+	var wg sync.WaitGroup
+	for run := 0; run < 2; run++ {
+		wg.Add(1)
+		go func() {
+			defer wg.Done()
+			meter := NewMeter(runBudget(6, time.Minute), time.Now(), nil)
+			result, err := runner.Run(context.Background(), 7, tasksFor("a", "b", "c", "d", "e", "f"), meter)
+			if err != nil || !result.Complete || len(result.Candidates) != 6 {
+				t.Errorf("result=%#v err=%v", result, err)
+			}
+		}()
+	}
+	wg.Wait()
+	if peak.Load() > 2 {
+		t.Fatalf("installation ran %d sub-agents at once across reviews; cap is 2", peak.Load())
+	}
+	if len(limiter.slots) != 0 {
+		t.Fatalf("idle installations retained: %d", len(limiter.slots))
+	}
+}
+
+func TestOrganizationsDoNotShareSlots(t *testing.T) {
+	limiter, _ := NewOrgLimiter(1)
+	holdA, err := limiter.Acquire(context.Background(), 1)
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer holdA()
+	ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
+	defer cancel()
+	holdB, err := limiter.Acquire(ctx, 2)
+	if err != nil {
+		t.Fatal("a busy installation blocked another installation")
+	}
+	holdB()
+	if _, err := limiter.Acquire(ctx, 1); !errors.Is(err, context.DeadlineExceeded) {
+		t.Fatalf("second slot for a capped installation: %v", err)
+	}
+}
+
+func TestPartialsStreamSeriallyAndAreProvisional(t *testing.T) {
+	limiter, _ := NewOrgLimiter(3)
+	var calls atomic.Int32
+	var seen []Partial
+	runner := Runner{
+		Limiter: limiter,
+		SubAgent: func(_ context.Context, task PlanTask, _ *Meter) ([]review.Finding, error) {
+			return []review.Finding{finding(task.BlockID+".go", 1, 1, "P1")}, nil
+		},
+		OnPartial: func(p Partial) {
+			if calls.Add(1) != 1 {
+				t.Error("OnPartial called concurrently")
+			}
+			seen = append(seen, p)
+			calls.Add(-1)
+		},
+	}
+	result, err := runner.Run(context.Background(), 7, tasksFor("a", "b", "c"), NewMeter(runBudget(3, time.Minute), time.Now(), nil))
+	if err != nil {
+		t.Fatal(err)
+	}
+	for i, p := range seen {
+		if p.Done != i+1 || p.Total != 3 || !p.Provisional || p.Outcome != TaskCompleted {
+			t.Fatalf("partial %d: %#v", i, p)
+		}
+	}
+	if result.Candidates[0].Path != "a.go" || result.Candidates[2].Path != "c.go" {
+		t.Fatalf("candidates must follow plan order, got %v", result.Candidates)
+	}
+}
+
+func TestFailuresAndPanicsStayInsideTheirTask(t *testing.T) {
+	limiter, _ := NewOrgLimiter(3)
+	runner := Runner{Limiter: limiter, SubAgent: func(_ context.Context, task PlanTask, _ *Meter) ([]review.Finding, error) {
+		switch task.BlockID {
+		case "boom":
+			panic("nil map")
+		case "bad":
+			return nil, fmt.Errorf("provider said: sk-live-secret rejected")
+		}
+		return []review.Finding{finding("ok.go", 1, 1, "P2")}, nil
+	}}
+	result, err := runner.Run(context.Background(), 7, tasksFor("ok", "bad", "boom"), NewMeter(runBudget(3, time.Minute), time.Now(), nil))
+	if err != nil || result.Complete || len(result.Candidates) != 1 {
+		t.Fatalf("result=%#v err=%v", result, err)
+	}
+	if result.Outcomes["boom"].Outcome != TaskFailed || result.Outcomes["bad"].Outcome != TaskFailed {
+		t.Fatalf("outcomes: %#v", result.Outcomes)
+	}
+	if strings.Contains(result.Outcomes["bad"].Reason, "secret") {
+		t.Fatal("provider error text leaked into the task reason")
+	}
+}
+
+func TestExhaustedBudgetSkipsUnstartedTasks(t *testing.T) {
+	limiter, _ := NewOrgLimiter(1)
+	runner := Runner{Limiter: limiter, SubAgent: func(_ context.Context, _ PlanTask, meter *Meter) ([]review.Finding, error) {
+		_, err := meter.Reserve(2_000, 1, 1)
+		return nil, err
+	}}
+	result, err := runner.Run(context.Background(), 7, tasksFor("a", "b", "c"), NewMeter(runBudget(3, time.Minute), time.Now(), nil))
+	if err != nil {
+		t.Fatal(err)
+	}
+	failed, skipped := 0, 0
+	for _, outcome := range result.Outcomes {
+		switch outcome.Outcome {
+		case TaskFailed:
+			failed++
+			if outcome.Reason != "review budget exhausted during this task" {
+				t.Fatalf("reason %q", outcome.Reason)
+			}
+		case TaskSkipped:
+			skipped++
+			if !strings.Contains(outcome.Reason, "input tokens") {
+				t.Fatalf("skip reason %q does not name the exhausted limit", outcome.Reason)
+			}
+		}
+	}
+	if failed != 1 || skipped != 2 || result.Complete {
+		t.Fatalf("failed=%d skipped=%d complete=%v", failed, skipped, result.Complete)
+	}
+}
+
+func TestWallTimeBoundsTheWholeRun(t *testing.T) {
+	limiter, _ := NewOrgLimiter(1)
+	runner := Runner{Limiter: limiter, SubAgent: func(ctx context.Context, _ PlanTask, _ *Meter) ([]review.Finding, error) {
+		<-ctx.Done()
+		return nil, ctx.Err()
+	}}
+	started := time.Now()
+	result, err := runner.Run(context.Background(), 7, tasksFor("a", "b"), NewMeter(runBudget(2, 30*time.Millisecond), started, nil))
+	if err != nil || time.Since(started) > time.Second {
+		t.Fatalf("run ignored the deadline: %v", err)
+	}
+	if result.Outcomes["a"].Outcome == TaskCompleted || result.Outcomes["b"].Outcome == TaskCompleted {
+		t.Fatalf("tasks completed past the deadline: %#v", result.Outcomes)
+	}
+}
+
+func TestRunRejectsInvalidPlans(t *testing.T) {
+	limiter, _ := NewOrgLimiter(1)
+	runner := Runner{Limiter: limiter, SubAgent: func(context.Context, PlanTask, *Meter) ([]review.Finding, error) { return nil, nil }}
+	meter := NewMeter(runBudget(2, time.Minute), time.Now(), nil)
+	for name, tasks := range map[string][]PlanTask{"empty": nil, "too many": tasksFor("a", "b", "c"), "duplicate": tasksFor("a", "a")} {
+		if _, err := runner.Run(context.Background(), 7, tasks, meter); err == nil {
+			t.Fatalf("%s accepted", name)
+		}
+	}
+	if _, err := NewOrgLimiter(0); err == nil {
+		t.Fatal("zero limit accepted")
+	}
+}
+
+func TestToolLimitAndContentionDoNotSkipOtherTasks(t *testing.T) {
+	limiter, _ := NewOrgLimiter(1)
+	runner := Runner{Limiter: limiter, SubAgent: func(_ context.Context, task PlanTask, meter *Meter) ([]review.Finding, error) {
+		switch task.BlockID {
+		case "tools":
+			for {
+				if err := meter.UseTool(task.BlockID); err != nil {
+					return nil, err
+				}
+			}
+		case "contended":
+			return nil, ErrBudgetContended
+		}
+		return []review.Finding{finding("ok.go", 1, 1, "P2")}, nil
+	}}
+	result, err := runner.Run(context.Background(), 7, tasksFor("tools", "contended", "ok"), NewMeter(runBudget(3, time.Minute), time.Now(), nil))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if result.Outcomes["tools"].Reason != "sub-agent reached its tool-call limit" || result.Outcomes["contended"].Outcome != TaskFailed || result.Outcomes["ok"].Outcome != TaskCompleted {
+		t.Fatalf("outcomes: %#v", result.Outcomes)
+	}
+}
